\set ON_ERROR_STOP on
begin;
create function public.test_assert(ok boolean,msg text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'ASSERTION FAILED: %',msg;end if;end$$;
create function public.test_raises(stmt text,expected text) returns void language plpgsql as $$begin execute stmt;raise exception 'Expected failure: %',expected;exception when others then if sqlerrm not like '%'||expected||'%' then raise;end if;end$$;
